#define CROW_HIP_ROLL_LIBRARY
#include "../crow-v15-hip-roll-strong-drive-prototype-20261111/probe.cpp"
#include <iomanip>
int main(){try{auto robot=hipRollModel();need(robot.mechanics.joints.at(4).axis0.y==1.f && robot.mechanics.joints.at(5).axis0.y==-1.f,"unexpected pronation axes");robot.mechanics.joints.at(5).axis0.y=1.f;const auto&m=robot.mechanics;std::cout<<std::setprecision(17);int lane,step;while(std::cin>>lane>>step){std::vector<double> q(m.defaultQ.size()),v(m.defaultV.size());for(auto&x:q)need(bool(std::cin>>x),"missing q");for(auto&x:v)need(bool(std::cin>>x),"missing v");std::vector<ArticulatedBodyKinematics> k(m.bodies.size());need(computeArticulatedBodyKinematics(m,0,q,v,k).succeeded(),"FK failed");double mass=0,c[3]={},cv[3]={};for(unsigned i=0;i<k.size();++i){double w=m.bodies[i].massAndInverseMass.x;mass+=w;for(int j=0;j<3;++j){c[j]+=w*k[i].centerOfMassPosition[j];cv[j]+=w*k[i].linearVelocity[j];}}std::cout<<"C "<<lane<<" "<<step<<" "<<mass;for(double x:c)std::cout<<" "<<x/mass;for(double x:cv)std::cout<<" "<<x/mass;for(int body:{0,5,6,7})for(int j=0;j<3;++j)std::cout<<" "<<k[body].centerOfMassPosition[j];std::cout<<std::endl;}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
